function evaluateJournal(){let changed=false;forecastJournal=forecastJournal.map(x=>{const before=JSON.stringify(x.evaluations||{}),n=J.evaluate(x,candleSets.M1?.bars||[]);if(JSON.stringify(n.evaluations)!==before)changed=true;return n});if(changed)saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal)}
