function renderMeasuredProbability(){if(!probabilityReport)return;const r=probabilityReport,fresh=Number.isFinite(r.expiresAt)&&Date.now()<=r.expiresAt;const pct=n=>(n*100).toFixed(1)+'%';
 $('probabilityStatus').textContent=(fresh?'نتيجة فحص تاريخي، وليست دقة حيّة مثبتة. ':'انتهت صلاحية مرجع الساعة؛ النسب محجوبة حتى إعادة الفحص. ')+r.bars+' شمعة • '+r.source+' • من '+new Date(r.start).toLocaleDateString('ar-LB')+' إلى '+new Date(r.end).toLocaleString('ar-LB')+' • الحالة الحالية: '+r.groupName+' • المؤشرات من آخر 48 شمعة متاحة ضمن '+r.featureSpanHours+' ساعة، دون ملء الفراغات.';
 const markup=r.horizons.map(h=>{const ready=fresh&&h.ready&&h.probabilities,labels={UP:'صعود',DOWN:'هبوط',FLAT:'ثبات'};return '<article class="measured-window"><h3>'+h.hours+' ساعة</h3>'+(ready?'<div class="measured-bars">'+Object.entries(labels).map(([key,label])=>'<div><span>'+label+'</span><b>'+pct(h.probabilities[key])+'</b></div>').join('')+'</div><p class="muted tiny">تقدير احتمالي تجريبي اجتاز شروط هذا الفحص التاريخي؛ لم تُثبت نتائجه الحيّة بعد.</p>':'<b>الاحتمال غير معتمد</b><p>'+escapeHtml(fresh?(h.reasons||[]).join(' • '):'البيانات تحتاج تحديثاً')+'</p>')+'<p class="muted tiny">حالات البناء المشابهة: '+h.trainingCases+' • الاختبار: '+h.validationCases+' • المشابهة بالاختبار: '+h.matchingValidationCases+'</p>'+(h.modelBrier!==null?'<p class="muted tiny">خطأ Brier للنموذج: '+h.modelBrier.toFixed(3)+' • المقارنة البسيطة: '+h.baselineBrier.toFixed(3)+' (الأقل أفضل)</p>':'')+(h.skillInterval95?'<p class="muted tiny">نطاق 95% لتفوق النموذج على المقارنة: '+h.skillInterval95.map(n=>n.toFixed(4)).join(' إلى ')+'؛ يجب أن يبقى موجباً لقبول التفوق.</p>':'')+(ready&&h.validationObserved?'<p class="muted tiny">نطاق 95% لتكرار الصعود في عينة الاختبار: '+h.validationObserved.UP.interval.map(pct).join(' – ')+'؛ لا يضمن احتواء الاحتمال الحقيقي للحالة القادمة.</p>':'')+'</article>'}).join('');if(markup!==probabilityMarkup){$('probabilityResults').innerHTML=markup;probabilityMarkup=markup;}}
$('measureProbabilityBtn').onclick=async()=>{if(probabilityBusy)return;probabilityBusy=true;probabilityReport=null;probabilityMarkup='';$('probabilityResults').innerHTML='';$('measureProbabilityBtn').disabled=true;$('probabilityStatus').textContent='جاري جلب التاريخ وفصل البناء عن الاختبار…';try{const response=await fetch('/api/probability',{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(28000)}),r=await response.json();if(!response.ok||r.model!=='gold-h1-frequency-v2'||!Array.isArray(r.horizons))throw Error(r.reasonAr||'لم يصل تقرير تاريخي صالح');probabilityReport=r;renderMeasuredProbability()}catch(e){$('probabilityStatus').textContent='لم تُعتمد أي نسبة: '+(e.name==='TimeoutError'?'انتهت مهلة المصدر؛ جرّب لاحقاً.':e.message)}finally{probabilityBusy=false;$('measureProbabilityBtn').disabled=false}};
function renderForecast(){currentForecast=Forecast.validReference(remoteForecast,candleSets.M15)?remoteForecast:currentLocalForecast();const f=currentForecast||{};$('forecastBasis').textContent=f.ready?'المرجع: إغلاق '+new Date(f.referenceTime).toLocaleString('ar-LB')+' • '+(live&&Q.quote({price,sourceTime:lastSourceTime}).usable?'السعر اللحظي حديث؛ التحليل مبني على الإغلاق.':'السعر اللحظي غير حديث؛ هذا تحليل آخر إغلاق، وليس تسعيرة تنفيذ.'):'بانتظار شموع تحليل صالحة؛ تحديث السعر وحده لا يكفي.';if(f.ready)recordForecast(f);const cls=f.action==='WATCH_BUY'?'buy':f.action==='WATCH_SELL'?'sell':'wait';$('forecastStatus').className='forecast-status '+cls;$('forecastStatus').textContent=f.ready?`${f.actionAr||'انتظار'} • ${f.sequenceAr||''} • جودة البيانات ${Math.round(f.dataQuality||0)}%`:(f.messageAr||'جاري تجهيز التوقع');
 const set=(p,h)=>{if(!h){$(p+'Bias').textContent='—';$(p+'Probability').textContent='—';$(p+'Range').textContent='—';$(p+'Confidence').textContent='—';$(p+'Invalidation').textContent='—';return}$(p+'Bias').textContent=h.biasAr||h.bias;$(p+'Probability').textContent='أوزان نموذج تجريبية؛ ليست احتمالات نجاح';$(p+'Range').textContent=`${money(h.low)} — ${money(h.high)}`;$(p+'Confidence').textContent=`درجة النموذج ${h.modelScore??'—'}/100 • المركز ${money(h.center)}`;$(p+'Invalidation').textContent=h.invalidation?`إلغاء السيناريو قرب ${money(h.invalidation)}`:'لا يوجد مستوى إلغاء اتجاهي'};set('f24',f.h24);set('f48',f.h48);
 $('forecastReasons').innerHTML=(f.reasonsAr||[]).slice(0,8).map(x=>`<span>${escapeHtml(x)}</span>`).join('');$('forecastWarning').hidden=!f.warningAr;$('forecastWarning').textContent=f.warningAr||'';$('macroStatus').textContent=`المصادر ${macro.status||'—'} • جودة ${Math.round(macro.quality||0)}% • الأثر العالمي ${macro.compositeScore==null?'غير متاح':Number(macro.compositeScore).toFixed(1)}`;const s=journalStats();$('forecastAccuracy').textContent=(s.h24.n||s.h48.n)?`نتائج هذا الإصدار: 24h ${s.h24.dir??'—'}% (${s.h24.n}) • 48h ${s.h48.dir??'—'}% (${s.h48.n})؛ ليست ضماناً للتوقع التالي`:'لا نتائج موثقة بعد؛ يلزم إغلاق M1 عند موعد 24/48 ساعة. السجل القديم غير محسوب.';renderAccuracy();renderContext();renderEvidence();renderHome()}
function factorDirection(name,v){if(!v||v.latest===null||v.latest===undefined||v.latest===''||!Number.isFinite(Number(v.latest)))return 'غير متاح';if(v.status&&v.status!=='available')return v.status==='stale'?'بيانات قديمة • '+(v.date||''):'بيانات غير كافية';if(v.changePct===null||v.changePct===undefined||!Number.isFinite(Number(v.changePct)))return 'تغير غير متاح';const ch=Number(v.changePct),supportive=['VIX','النفط'].includes(name)?ch>0:ch<0,unit=v.unit==='percentage-points'?' نقطة مئوية':'%';return `${Number(v.latest).toFixed(2)} • ${ch>=0?'+':''}${ch.toFixed(2)}${unit} • ${ch===0?'دون تغير':supportive?'داعم محتمل':'ضاغط محتمل'}${v.date?' • '+v.date:''}`}

function marketRegime(){const news=Math.abs(Number(macro.news?.score)||0),vix=Number(macro.factors?.vix?.changePct)||0;if(calendar.risk24h)return '⚠️ سوق أخبار عالية التأثير';if(news>=20)return '🌍 سوق أخبار/جيوسياسة';if(lastAnalysis?.ready&&Number(lastAnalysis.strength)>=80)return '📈 اتجاه فني قوي';if(vix>5)return '🛡️ سوق توتر/ملاذ آمن';return '↔️ سوق مختلط/متذبذب'}
function renderMacro(){$('marketRegime').textContent=marketRegime();const f=macro.factors||{},items=[['الدولار',f.usd],['عائد 10 سنوات',f.yield10],['عائد سنتين',f.yield2],['الفائدة الفعلية',f.fedFunds],['VIX',f.vix],['S&P 500',f.sp500],['Nasdaq',f.nasdaq],['النفط',f.oil]];$('macroFactors').innerHTML=items.filter(([,v])=>v).map(([n,v])=>`<div><span>${n}</span><b class="${factorDirection(n,v).includes('داعم محتمل')?'up':factorDirection(n,v).includes('ضاغط محتمل')?'down':'muted'}">${escapeHtml(factorDirection(n,v))}</b></div>`).join('')||'<div><span>العوامل</span><b>بانتظار الاتصال</b></div>';
 const news=macro.news?.headlines||[];$('newsRadar').innerHTML=news.slice(0,8).map(x=>`<li>${escapeHtml(x.title||'')} ${x.domain?`<small>— ${escapeHtml(x.domain)}</small>`:''}</li>`).join('')||'<li>لا توجد عناوين متاحة حالياً.</li>'}
function eventCountdown(ts){const ms=Number(ts)-Date.now();if(ms<=0)return 'الآن/صدر';const m=Math.round(ms/60000),d=Math.floor(m/1440),h=Math.floor((m%1440)/60),min=m%60;if(d)return `بعد ${d}ي ${h}س`;if(h)return `بعد ${h}س ${min}د`;return `بعد ${min}د`}
function renderCalendar(){const events=(calendar.events||[]).filter(e=>Number(e.timestamp)>Date.now()-3600000).slice(0,10),n=calendar.nextHigh;$('calendarStatus').textContent=`${calendar.status||'—'} • ${events.length} أحداث قادمة${calendar.errors?.length?' • بعض المصادر متأخرة':''}`;$('nextEvent').innerHTML=n?`<b>⚠️ ${escapeHtml(n.titleAr||n.title)}</b><small>${eventCountdown(n.timestamp)} • ${new Date(n.timestamp).toLocaleString('ar')} • ${escapeHtml(n.source||'')}</small>`:'<b>لا يوجد حدث عالي التأثير قريب ضمن البيانات المتاحة.</b>';$('calendarEvents').innerHTML=events.map(e=>`<div class="event-row"><div class="event-time">${new Date(e.timestamp).toLocaleDateString('ar',{month:'short',day:'numeric'})}<br>${new Date(e.timestamp).toLocaleTimeString('ar',{hour:'2-digit',minute:'2-digit'})}</div><div><b>${escapeHtml(e.titleAr||e.title)}</b><small>${escapeHtml(e.source||'')} • ${eventCountdown(e.timestamp)}</small></div><span class="impact ${e.impact==='high'?'high':'medium'}">${e.impact==='high'?'عالي':'متوسط'}</span></div>`).join('')||'<div class="muted">لا توجد أحداث في القائمة الآن.</div>'}
function renderPaper(){if(!paper||typeof paper!=='object')paper={startCash:10000,cash:10000,oz:0,avgCost:0,realized:0,trades:[],auto:false,lastAutoSignal:'WAIT'};const equity=Number(paper.cash||0)+Number(paper.oz||0)*Number(price||0),pl=equity-Number(paper.startCash||10000);$('paperCash').textContent=money(paper.cash);$('paperOz').textContent=(Number(paper.oz)||0).toFixed(4)+' oz';$('paperEquity').textContent=money(equity);$('paperPL').textContent=(pl>=0?'+':'')+money(pl);$('paperPL').style.color=pl>0?'var(--buy)':pl<0?'var(--sell)':'';$('paperAuto').checked=!!paper.auto;$('paperRows').innerHTML=(paper.trades||[]).slice(-12).reverse().map(t=>`<tr><td>${new Date(t.time).toLocaleString('ar')}</td><td>${t.side==='BUY'?'شراء':'بيع'}</td><td>${money(t.execPrice)}</td><td>${Number(t.oz).toFixed(4)}</td><td>${money(t.value)}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد صفقات تجريبية.</td></tr>'}
function paperBuy(amount,auto=false){amount=Math.min(Math.max(0,Number(amount)||0),Number(paper.cash||0));if(!live||!Q.quote({price,sourceTime:lastSourceTime}).usable||!(price>0)||amount<10)return false;const exec=price*(1+SPREAD),oz=amount/exec,oldOz=Number(paper.oz||0),oldCost=oldOz*Number(paper.avgCost||0);paper.cash-=amount;paper.oz=oldOz+oz;paper.avgCost=(oldCost+amount)/paper.oz;paper.trades=[...(paper.trades||[]),{time:Date.now(),side:'BUY',marketPrice:price,execPrice:exec,oz,value:amount,auto}].slice(-300);saveJSON(userKey('gold_paper'),paper);renderPaper();return true}
function paperSell(auto=false){const oz=Number(paper.oz||0);if(!live||!Q.quote({price,sourceTime:lastSourceTime}).usable||!(price>0)||oz<=0)return false;const exec=price*(1-SPREAD),value=oz*exec,cost=oz*Number(paper.avgCost||0);paper.cash+=value;paper.realized=Number(paper.realized||0)+(value-cost);paper.trades=[...(paper.trades||[]),{time:Date.now(),side:'SELL',marketPrice:price,execPrice:exec,oz,value,auto}].slice(-300);paper.oz=0;paper.avgCost=0;saveJSON(userKey('gold_paper'),paper);renderPaper();return true}
function maybePaperAuto(a){if(!paper.auto||!a?.ready)return;if(a.side==='WAIT'){paper.lastAutoSignal='WAIT';saveJSON(userKey('gold_paper'),paper);return}const threshold=a.side==='BUY'?Number(C.buyThreshold||75):Number(C.sellThreshold||75);if(a.strength<threshold||paper.lastAutoSignal===a.side)return;if(a.side==='BUY')paperBuy(Math.min(1000,Number(paper.cash||0)*.25),true);if(a.side==='SELL')paperSell(true);paper.lastAutoSignal=a.side;saveJSON(userKey('gold_paper'),paper)}
function render(){if(!(price>0))return;const a=Engine.analyze({connected:live,quote:{price,sourceTime:lastSourceTime},candles:candleSets},C);lastAnalysis=a;$('price').textContent=money(price);renderPhysical();
 const sig=$('signal');sig.textContent=a.side;sig.className='signal '+String(a.side||'WAIT').toLowerCase();$('rsi').textContent=a.rsi==null?'—':Number(a.rsi).toFixed(1);$('ema').textContent=a.ema9&&a.ema21?(a.ema9>a.ema21?'↑ صاعد':'↓ هابط'):'—';$('momentum').textContent=a.momentum==null?'—':`${a.momentum>=0?'+':''}${Number(a.momentum).toFixed(3)}%`;$('strength').textContent=(a.strength||0)+'/100';$('warmup').textContent=a.ready?'':(a.reasonsAr?.[0]||'بانتظار شموع موثقة');$('sampleCount').textContent=`${history.length} قراءة حقيقية`;
 const plan=a.plan||{};$('entry').textContent=a.plan?money(plan.entry):'—';$('sl').textContent=money(plan.stopLoss);$('tp1').textContent=money(plan.takeProfit1);$('tp2').textContent=money(plan.takeProfit2);$('signalReasons').innerHTML=(lang==='ar'?a.reasonsAr:a.reasons).map(x=>`<span>${escapeHtml(x)}</span>`).join('');renderQuality();drawChart();renderForecast();renderMacro();renderCalendar();renderPaper();applyLang();updateTime();maybePaperAuto(a)}
function drawChart(){const samples=R.summary(observedQuotes).samples.slice(-720);$('sampleCount').textContent=samples.length+' قراءة مرصودة • خط متقطع عند الفجوات';if(!samples.length){$('line').setAttribute('d','');$('area').setAttribute('d','');return}const w=600,h=220,pad=14,vals=samples.map(r=>r.price),min=Math.min(...vals),max=Math.max(...vals),range=Math.max(max-min,.01),first=samples[0].sourceTime,span=Math.max(30000,samples.at(-1).sourceTime-first);let path='';const pts=samples.map((r,i)=>{const x=pad+(r.sourceTime-first)/span*(w-pad*2),y=pad+(1-(r.price-min)/range)*(h-pad*2);path+=(i===0||r.sourceTime-samples[i-1].sourceTime>R.GAP?'M ':' L ')+x+' '+y;return [x,y]});$('line').setAttribute('d',path);$('area').setAttribute('d','');$('lastPoint').setAttribute('cx',pts.at(-1)[0]);$('lastPoint').setAttribute('cy',pts.at(-1)[1])}
function animatePrice(next){if(previousPrice==null){previousPrice=next;return}const diff=next-previousPrice,p=previousPrice?diff/previousPrice*100:0;$('priceArrow').textContent=diff>0?'▲':diff<0?'▼':'•';$('priceArrow').className='price-arrow '+(diff>0?'up':diff<0?'down':'');$('priceChange').textContent=`${diff>0?'+':''}${diff.toFixed(2)} (${p>0?'+':''}${p.toFixed(3)}%)`;$('priceChange').className='price-change '+(diff>0?'up':diff<0?'down':'');$('price').classList.remove('flash-up','flash-down');void $('price').offsetWidth;if(diff!==0)$('price').classList.add(diff>0?'flash-up':'flash-down');previousPrice=next}
function renderQuality(){renderHome();renderPurchaseTime();renderPhysical();renderRecorder();const q=Q.quote({price,sourceTime:lastSourceTime}),usable=live&&q.usable;quoteState=q;const message=live?(Q.reasons[q.status]||q.status):'الاتصال مقطوع؛ الإشارات معلّقة';$('feedStatus').textContent=usable?'سعر حديث':message;$('liveDot').classList.toggle('on',usable);$('dataQualityStatus').textContent=message+(quoteSource?' • المصدر: '+quoteSource:'');$('candleStatus').textContent=['M1','M5','M15'].map(tf=>{const set=candleSets[tf];const checked=Q.candles({symbol:set?.symbol,source:set?.source,timeframe:tf,candles:set?.bars||[]},tf);return tf+': '+(checked.ready?checked.bars.length+' شمعة مغلقة من '+(set.source||'المصدر'):(set?.reasonAr||checked.reasonAr))}).join(' • ');$('candlePerformance').textContent=(candleRequestMs===null?'لم يُقَس طلب الشموع بعد':'زمن معالجة آخر طلب شموع بالخادم: '+candleRequestMs+' ms')+(candleSets.M1?.latestNativeClosedEnd?' • عمر آخر إغلاق M1 بالمصدر: '+Math.max(0,Math.round((Date.now()-candleSets.M1.latestNativeClosedEnd)/1000))+'ث':'')+' • طلب مجمّع كل '+Math.round(candleRefreshMs/1000)+' ثانية تقريباً • قد يُعلّق M1 بين التحديثات إذا تأخرت الشموع';$('journalStatus').textContent=(journalStatus==='CONNECTED'?'السجل السحابي متصل':journalStatus==='NOT_CONFIGURED'?'الحفظ محلي؛ التخزين السحابي غير مفعّل':'الحفظ محلي؛ المزامنة غير متاحة')+(legacyCount?' • '+legacyCount+' توقع قديم مستبعد من الدقة':'');if(!usable){$('signal').textContent='WAIT';$('signal').className='signal wait';$('strength').textContent='—';for(const id of ['entry','sl','tp1','tp2'])$(id).textContent='—';lastAnalysis=null;}}
async function fetchLive(){try{const r=await fetch((C.marketProxy||'/api/market')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(12000)});if(r.status===401){localStorage.removeItem('gold_token');location.replace('/login');return}const j=await r.json();if(!r.ok)throw Error('Market error');const q=Q.quote(j);quoteRefreshMs=Math.min(60000,Math.max(2000,Number(j.refreshAfterMs)||3000));quoteSource=String(j.source||'').slice(0,120);if(!(q.price>0))throw Error('Invalid price');animatePrice(q.price);price=q.price;lastSourceTime=q.sourceTime;lastFetchAt=Date.now();live=true;if(q.usable){addPoint(price,q.sourceTime);recordQuote({...j,symbol:j.symbol,source:quoteSource})}render()}catch(e){live=false;remoteForecast=null;renderQuality();renderForecast();console.warn('Market feed unavailable')}finally{clearTimeout(pollTimer);pollTimer=setTimeout(fetchLive,Math.max(quoteRefreshMs,Math.max(2,Number(C.pollSeconds)||3)*1000))}}
async function fetchCandles(){try{const r=await fetch('/api/candles?timeframe=ALL',{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(15000)}),j=await r.json();if(!r.ok||!j.timeframes)throw Error();for(const tf of ['M1','M5','M15'])candleSets[tf]=j.timeframes[tf]||{ready:false,bars:[],reasonAr:'إطار غير متاح'};candleRequestMs=Number.isFinite(j.requestMs)?j.requestMs:null;candleRefreshMs=Math.max(60000,Math.min(3600000,Number(j.refreshAfterMs)||60000))}catch{for(const tf of ['M1','M5','M15'])candleSets[tf]={ready:false,reasonAr:'تعذّر تحميل شموع '+tf,bars:[]};candleRequestMs=null}finally{evaluateJournal();if(price>0)render();else renderQuality();clearTimeout(candleTimer);candleTimer=setTimeout(fetchCandles,candleRefreshMs)}}
async function syncJournal(){if(journalBusy)return;journalBusy=true;try{const r=await fetch('/api/journal'+($('journalMonth').value?'?month='+encodeURIComponent($('journalMonth').value):''),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(12000)}),j=await r.json();journalStatus=j.status||'UNAVAILABLE';if(r.ok&&j.status==='CONNECTED'){const selected=$('journalMonth').value;$('journalMonth').innerHTML='<option value="">آخر شهرين</option>'+(j.availableMonths||[]).slice().reverse().map(m=>/^\d{4}-(0[1-9]|1[0-2])$/.test(m)?'<option value="'+m+'">'+m+'</option>':'').join('');$('journalMonth').value=selected;if(selected){archiveJournal=j.entries||[]}else{archiveJournal=null;forecastJournal=J.merge(j.entries||[],forecastJournal);saveJSON(userKey('gold_forecast_journal_v42'),forecastJournal)}renderAccuracy()}}catch{journalStatus='UNAVAILABLE'}finally{journalBusy=false;renderQuality()}}
async function fetchIntelligence(force=false){if(!force&&macroFetchAt&&Date.now()-macroFetchAt<Math.max(5,Number(C.macroRefreshMinutes)||30)*60000)return;try{let r=await fetch((C.forecastProxy||'/api/forecast')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(30000)}),j=await r.json();if(!r.ok)throw Error('Forecast feed error');remoteForecast=j.forecast||null;macro=j.macro||macro;calendar=j.calendar||calendar;macroFetchAt=calendarFetchAt=Date.now();saveJSON('gold_macro_cache',macro);saveJSON('gold_remote_forecast',remoteForecast);saveJSON('gold_calendar_cache',calendar);render()}catch(e){macro={...macro,status:'unavailable',quality:0,compositeScore:null,factors:{},reasonsAr:['تعذر تحديث البيانات الاقتصادية؛ النسخة القديمة مستبعدة من التحليل.'],reasons:[]};remoteForecast=null;calendar=readJSON('gold_calendar_cache',calendar);if(macro)macro={...macro,status:'stale'};console.warn(e);render()}}
async function fetchCalendar(force=false){if(!force&&calendarFetchAt&&Date.now()-calendarFetchAt<15*60000)return;try{const r=await fetch((C.calendarProxy||'/api/calendar')+'?ts='+Date.now(),{headers:authHeaders(),cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(j.error||'Calendar feed error');calendar=j;calendarFetchAt=Date.now();saveJSON('gold_calendar_cache',calendar);renderCalendar();renderForecast()}catch(e){console.warn(e);calendar=readJSON('gold_calendar_cache',calendar);renderCalendar()}}
function updateTime(){renderMeasuredProbability();renderQuality();renderForecast();if(!lastFetchAt){$('lastUpdate').textContent='بانتظار أول قراءة';return}const s=Math.max(0,Math.floor((Date.now()-lastFetchAt)/1000)),source=lastSourceTime?new Date(lastSourceTime).toLocaleTimeString(lang==='ar'?'ar':'en',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'';$('lastUpdate').textContent=lang==='ar'?`آخر اتصال منذ ${s}ث • عمر السعر ${lastSourceTime?Math.max(0,Math.floor((Date.now()-lastSourceTime)/1000))+'ث':'غير معروف'} ${source?'• '+source:''}`:`Connected ${s}s ago ${source?'• price '+source:''}`;renderCalendar()}
function applyLang(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-i]').forEach(e=>{const k=e.dataset.i;if(!tr[lang]?.[k])return;const b=e.querySelector('b');if(b){const node=b.cloneNode(true);e.textContent=tr[lang][k];e.appendChild(node)}else e.textContent=tr[lang][k]});$('langBtn').textContent=lang==='ar'?'EN':'AR'}

